# --- new imports near the top ---
from rank_bm25 import BM25Okapi
import re
import threading

# --- new config flag ---
HYBRID_ENABLED = os.getenv("HYBRID_RETRIEVAL", "true").lower() == "true"
RRF_K = int(os.getenv("RRF_K", 60))
BM25_TOP_K = int(os.getenv("BM25_TOP_K", 30))

# --- module-level BM25 cache (built lazily once per process) ---
_bm25_lock = threading.Lock()
_bm25_state = {"index": None, "docs": None, "point_ids": None}

def _tokenize(text: str):
    # Simple bilingual tokenizer: lowercase, split on non-word.
    # Keep Thai chars as a single block split on whitespace (rank_bm25
    # uses bag-of-tokens; exact-match tokens are what matter here).
    text = text.lower()
    return re.findall(r"\w+", text, flags=re.UNICODE)

def _build_bm25_index():
    """Scroll every point out of Qdrant once and build an in-memory
    BM25Okapi index. 49 chunks today, fits trivially in RAM."""
    from qdrant_client import models
    client = get_qdrant_client()
    collection = get_collection_name()
    docs, point_ids = [], []
    offset = None
    while True:
        results, offset = client.scroll(
            collection_name=collection,
            limit=256,
            offset=offset,
            with_payload=True,
        )
        for p in results:
            payload = p.payload or {}
            # langchain-qdrant stores text under 'page_content'
            content = payload.get("page_content") or payload.get("content") or ""
            if content:
                docs.append({"content": content, "source": payload.get("metadata", {}).get("source") or payload.get("source", "unknown")})
                point_ids.append(str(p.id))
        if offset is None:
            break
    tokenized = [_tokenize(d["content"]) for d in docs]
    index = BM25Okapi(tokenized) if tokenized else None
    _bm25_state["index"] = index
    _bm25_state["docs"] = docs
    _bm25_state["point_ids"] = point_ids
    logger.info(f"BM25 index built: {len(docs)} chunks")

def _get_bm25():
    if _bm25_state["index"] is None:
        with _bm25_lock:
            if _bm25_state["index"] is None:
                _build_bm25_index()
    return _bm25_state

# --- inside document_search(), replace the 'no reranker' branch ---
# After vector retrieval into `docs` (top_k_retrieval candidates):
if HYBRID_ENABLED and self.reranker is None:
    bm25 = _get_bm25()
    if bm25["index"] is not None:
        tokens = _tokenize(content)
        scores = bm25["index"].get_scores(tokens)
        # Rank BM25 corpus by score desc, keep top BM25_TOP_K
        bm25_ranked = sorted(
            range(len(scores)), key=lambda i: scores[i], reverse=True
        )[:BM25_TOP_K]
        bm25_docs = [bm25["docs"][i] for i in bm25_ranked]

        # Build vector ranking keyed by content (LangChain doesn't expose
        # point ids; content equality is reliable for our 49-chunk corpus)
        vec_rank = {d.page_content: r for r, d in enumerate(docs)}
        bm25_rank = {d["content"]: r for r, d in enumerate(bm25_docs)}

        # RRF fusion
        all_contents = set(vec_rank) | set(bm25_rank)
        fused = []
        for c in all_contents:
            score = 0.0
            if c in vec_rank:
                score += 1.0 / (RRF_K + vec_rank[c])
            if c in bm25_rank:
                score += 1.0 / (RRF_K + bm25_rank[c])
            fused.append((c, score))
        fused.sort(key=lambda x: x[1], reverse=True)

        # Materialise top num_docs back into result dicts.
        content_to_doc = {d.page_content: d for d in docs}
        bm25_content_to_doc = {d["content"]: d for d in bm25_docs}
        results = []
        for c, score in fused[:num_docs]:
            if c in content_to_doc:
                d = content_to_doc[c]
                results.append({
                    "source": d.metadata.get("source", "unknown"),
                    "content": d.page_content,
                    "score": score,
                })
            else:
                d = bm25_content_to_doc[c]
                results.append({
                    "source": d["source"],
                    "content": d["content"],
                    "score": score,
                })
        logger.info(f"Returning {len(results)} hybrid (RRF) results")
        # fall through to audit logging
    else:
        # BM25 build failed (empty collection?) — fall back to vector only
        results = [
            {"source": d.metadata.get("source", "unknown"),
             "content": d.page_content, "score": 0.0}
            for d in docs[:num_docs]
        ]
